-- Record templates (#145): the encrypted template payload of every medical record, and the templates of the types
-- the #144 migration created. Only types still named Individual/Familia and still on the empty template are filled;
-- a migrated type renamed before this deploy keeps its empty template. Individual turns on family members, which
-- today's individual form shows.

ALTER TABLE "medical_records" ADD COLUMN "data" TEXT;

UPDATE "patient_types" SET "template" = $individual${"sections":[{"title":"Datos generales","fields":[{"key":"consultationReason","label":"Motivo de consulta","kind":"longText","required":false,"removedAt":null}]},{"title":"Composición familiar","fields":[{"key":"familyObservations","label":"Observaciones","kind":"longText","required":false,"removedAt":null}]},{"title":"Antecedentes","fields":[{"key":"earlyDevelopment","label":"Desarrollo temprano","kind":"longText","required":false,"removedAt":null},{"key":"schoolAndWork","label":"Escolar y laboral","kind":"longText","required":false,"removedAt":null},{"key":"lifestyleHabits","label":"Hábitos y estilo de vida","kind":"longText","required":false,"removedAt":null},{"key":"traumaticEvents","label":"Eventos traumáticos o estresores previos","kind":"longText","required":false,"removedAt":null},{"key":"emotionalConsiderations","label":"Consideraciones emocionales","kind":"longText","required":false,"removedAt":null},{"key":"physicalConsiderations","label":"Consideraciones físicas, etiología y de salud","kind":"longText","required":false,"removedAt":null},{"key":"mentalHistory","label":"Antecedentes mentales","kind":"longText","required":false,"removedAt":null},{"key":"objective","label":"Objetivo","kind":"longText","required":false,"removedAt":null}]}]}$individual$::jsonb, "familyMembersEnabled" = true
WHERE "name" = 'Individual' AND "template" = '{"sections": []}'::jsonb;

UPDATE "patient_types" SET "template" = $familia${"sections":[{"title":"Datos generales","fields":[{"key":"consultationReason","label":"Motivo de consulta","kind":"longText","required":false,"removedAt":null}]},{"title":"Aspectos específicos de la familia","fields":[{"key":"familyType","label":"Tipo de familia","kind":"longText","required":false,"removedAt":null},{"key":"lifecycle","label":"Ciclo vital","kind":"longText","required":false,"removedAt":null},{"key":"genogram","label":"Genograma","kind":"longText","required":false,"removedAt":null},{"key":"resources","label":"Recursos que tienen","kind":"longText","required":false,"removedAt":null},{"key":"difficulties","label":"Dificultades tienen","kind":"longText","required":false,"removedAt":null},{"key":"communication","label":"Comunicación","kind":"longText","required":false,"removedAt":null},{"key":"rule","label":"Reglas","kind":"longText","required":false,"removedAt":null},{"key":"limits","label":"Limites","kind":"longText","required":false,"removedAt":null},{"key":"familyContext","label":"Contexto familiar","kind":"longText","required":false,"removedAt":null},{"key":"expectations","label":"Expectativas","kind":"longText","required":false,"removedAt":null},{"key":"flexibility","label":"Flexibilidad al cambio","kind":"longText","required":false,"removedAt":null}]}]}$familia$::jsonb
WHERE "name" = 'Familia' AND "template" = '{"sections": []}'::jsonb;
